const FACE: Record<string, Dir> = { d: 'down', u: 'up', n: 'north', s: 'south', w: 'west', e: 'east' };

function toCube(c: Cube): EntityCube {
  const [u, v, x, y, z, w, h, d, grow, mirror, faces] = c;
  return {
    uv: [u, v],
    from: [x, y, z],
    size: [w, h, d],
    inflate: grow === undefined ? undefined : typeof grow === 'number' ? grow : (grow as Vec3),
    mirror: mirror ? true : undefined,
    faces: faces ? [...faces].map((f) => FACE[f]) : undefined,
  };
}

function toPart(p: Part): EntityPart {
  const [name, pose, cubes, children] = p;
  const [x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0, sx = 1, sy = 1, sz = 1] = pose;
  return {
    name,
    cubes: cubes.map(toCube),
    pose: { offset: [x, y, z], rotation: [rx, ry, rz], scale: sx !== 1 || sy !== 1 || sz !== 1 ? [sx, sy, sz] : undefined },
    children: children?.map(toPart),
  };
}

const cache = new Map<string, EntityModel>();

/** A mob model layer by name ('creeper', 'sheep#wool', 'drowned#outer'...), or null. */
export function mobLayer(name: string): EntityModel | null {
  let m = cache.get(name);
  if (m) return m;
  const l = LAYERS[name];
  if (!l) return null;
  m = { texSize: [l[0], l[1]], parts: [toPart(l[2])] };
  cache.set(name, m);
  return m;
}

/** Every layer name (tests). */
export function mobLayerNames(): string[] {
  return Object.keys(LAYERS);
}
